import math

def trapezoid_duration(d, v_max, a_max):
    """Duration of the fastest rest-to-rest move of length d > 0 under the two limits."""
    if d < v_max * v_max / a_max:              # triangle: never reaches v_max
        return 2.0 * math.sqrt(d / a_max)
    return d / v_max + v_max / a_max

def trapezoid(d, v_max, a_max, t):
    """Position, velocity and acceleration at time t of that move (constant after the end)."""
    v = min(v_max, math.sqrt(d * a_max))       # the speed actually reached
    ta = v / a_max
    T = trapezoid_duration(d, v_max, a_max)
    t = min(max(t, 0.0), T)
    if t < ta:
        return 0.5 * a_max * t * t, a_max * t, a_max
    if t <= T - ta:
        return 0.5 * a_max * ta * ta + v * (t - ta), v, 0.0
    r = T - t
    if r == 0.0:
        return d, 0.0, 0.0
    return d - 0.5 * a_max * r * r, a_max * r, -a_max

