import numpy as np

def _f(x, tau):
    q, dq = x
    return np.array([dq, (tau - 0.1 * dq - 1.5 * 9.81 * 0.3 * np.sin(q)) / (1.5 * 0.3**2 + 0.02)])

def _ref(t):
    w = 2 * np.pi * 0.5
    return 1.0 + 0.8 * np.sin(w * t), 0.8 * w * np.cos(w * t), -0.8 * w * w * np.sin(w * t)

def _track(seconds=3.0, dt=0.001):
    x, worst = np.array([1.0, 0.0]), 0.0
    for k in range(int(round(seconds / dt))):
        qd, dqd, ddqd = _ref(k * dt)
        tau = float(control(x[0], x[1], qd, dqd, ddqd))
        k1 = _f(x, tau); k2 = _f(x + dt / 2 * k1, tau); k3 = _f(x + dt / 2 * k2, tau); k4 = _f(x + dt * k3, tau)
        x = x + dt / 6 * (k1 + 2 * k2 + 2 * k3 + k4)
        if k * dt >= 0.5:
            worst = max(worst, abs(_ref((k + 1) * dt)[0] - x[0]))
    return worst

_w = _track()
assert _w < 0.002, f"after 0.5 s the tracking error reaches {_w * 1000:.1f} mrad; computed torque should keep it below 2 mrad"
assert abs(control(0.3, 0.0, 0.3, 0.0, 0.0) - 1.5 * 9.81 * 0.3 * np.sin(0.3)) < 1e-6, "with no error and no motion, the torque should exactly hold the pendulum against gravity"
